func newTrackingEvent() unsafe.Pointer { return unsafe.Pointer(new(trackingevent.TrackingEvent)) }

func newNTrackingEvent(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]trackingevent.TrackingEvent, n)))
}

func ptrTrackingEvent(p unsafe.Pointer, c int32) any {
	r := (*trackingevent.TrackingEvent)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return (*string)(unsafe.Pointer(&r.ShipmentID))
	case 4:
		return (*string)(unsafe.Pointer(&r.ShipmentMoveID))
	case 5:
		return (*string)(unsafe.Pointer(&r.StopID))
	case 6:
		return (*string)(unsafe.Pointer(&r.Source))
	case 7:
		return &r.SourceKey
	case 8:
		return (*string)(unsafe.Pointer(&r.Kind))
	case 9:
		return (*string)(unsafe.Pointer(&r.MatchMethod))
	case 10:
		return &r.EventAt
	case 11:
		return &r.ReceivedAt
	case 12:
		return &r.Latitude
	case 13:
		return &r.Longitude
	case 14:
		return &r.SourceStatus
	case 15:
		return &r.RawReference
	case 16:
		return (*string)(unsafe.Pointer(&r.ReportedByID))
	case 17:
		return (*string)(unsafe.Pointer(&r.Outcome))
	case 18:
		return &r.OutcomeReason
	case 19:
		return &r.CreatedAt
	case 20:
		return &r.UpdatedAt
	}
	return nil
}

func valueTrackingEvent(p unsafe.Pointer, c int32) any {
	r := (*trackingevent.TrackingEvent)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return string(r.ShipmentID)
	case 4:
		return string(r.ShipmentMoveID)
	case 5:
		return string(r.StopID)
	case 6:
		return string(r.Source)
	case 7:
		return r.SourceKey
	case 8:
		return string(r.Kind)
	case 9:
		return string(r.MatchMethod)
	case 10:
		return r.EventAt
	case 11:
		return r.ReceivedAt
	case 12:
		if r.Latitude == nil {
			return nil
		}
		return *r.Latitude
	case 13:
		if r.Longitude == nil {
			return nil
		}
		return *r.Longitude
	case 14:
		if r.SourceStatus == "" {
			return nil
		}
		return r.SourceStatus
	case 15:
		if r.RawReference == "" {
			return nil
		}
		return r.RawReference
	case 16:
		if r.ReportedByID == "" {
			return nil
		}
		return string(r.ReportedByID)
	case 17:
		return string(r.Outcome)
	case 18:
		if r.OutcomeReason == "" {
			return nil
		}
		return r.OutcomeReason
	case 19:
		return r.CreatedAt
	case 20:
		return r.UpdatedAt
	}
	return nil
}

